import {LocalStore,KEY,TYPES,today,yearsBefore,date,emptyData,envelope,readEnvelope,parseText,toText,patientById,ageMonths,vaccineStatus,stockStatus} from './core.mjs';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Date(d+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):'—';
const titles={overview:'A good day to care.',mothers:'Maternal profiles',children:'Child profiles',visits:'Visits & notes',vaccines:'Vaccinations',growth:'Child growth',inventory:'Vaccine inventory',guides:'Care guides',backup:'Data & backup'};
const singles={mothers:'maternal profile',children:'child profile',visits:'visit',vaccines:'vaccination',growth:'measurement',inventory:'vaccine batch'};
const descriptions={mothers:'Every mother, a story worth keeping close.',children:'Small beginnings. A growing care story.',visits:'Checkups, symptoms, food intake, and the details that matter.',vaccines:'Staff-entered schedules and administered doses. Alerts stay on screen.',growth:'Measurements over time, with your own assessment notes.',inventory:'Batch-level stock, low-stock thresholds, and expiration dates.'};
let store;
try { store=new LocalStore(window.localStorage);store.load(); }
catch { store={data:emptyData(),raw:null,blocked:true,error:'Browser storage is unavailable. Allow storage for this site before entering records.',save(){throw new Error(this.error);},commit(){throw new Error(this.error);}}; }
let page='overview',query='',filter='All',editing=null,importStage=null,installEvent=null,toastTimer,offlineReady=false;
let lastFocus=null,formBaseline='';
const data=()=>store.data;
$('.skip-link').addEventListener('click',e=>{e.preventDefault();const target=$('#workspace-view').hidden?$('#main'):$('#workspace-main');target.tabIndex=-1;target.focus();});
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function info(title,body){$('#info-title').textContent=title;$('#info-body').innerHTML=body;$('#info-dialog').showModal();}
$('#close-info').onclick=()=>$('#info-dialog').close();
function updateStorageNotice(){const warning=$('#storage-warning');warning.hidden=!store.blocked;warning.textContent=store.error;if(store.blocked){const a=document.createElement('a');a.href='#workspace/backup';a.textContent=' Open Data & backup to recover.';warning.append(a);}}
const patientLabel=id=>{const p=patientById(data(),id);return p?`${p.name} · ${p.id}`:id;};
const badge=s=>`<span class="badge ${['Overdue','Expired'].includes(s)?'danger':['Due today','Low stock','Follow-up needed'].includes(s)?'warning':['Inactive','Not assessed'].includes(s)?'muted':''}">${escape(s)}</span>`;
function heading(title,description='',button=''){return `<div class="page-heading"><div><p class="eyebrow">YOUR COMMUNITY, CLOSE.</p><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${button}</div>`;}
function addButton(type,label){return `<button class="button primary" data-add="${type}">+ ${label??`Add ${singles[type]}`}</button>`;}
function editButton(type,id,label='View & edit'){return `<button class="row-button" data-edit="${type}" data-id="${escape(id)}" aria-label="${escape(label+' '+(data()[type].find(r=>r.id===id)?.name??singles[type]))}">${label} ↗</button>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map((c,i)=>`<td data-label="${escape(headers[i])}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function empty(type,searching=false){return `<div class="empty-state"><span class="empty-mark" aria-hidden="true">${type==='children'?'✳':'♡'}</span><h2>${searching?'No matching records.':`A place for every ${type==='mothers'?'mother':type==='children'?'little one':'care detail'}.`}</h2><p>${searching?'Try another name, ID, or filter.':`Your ${titles[type].toLowerCase()} will appear here. Start with a ${singles[type]}.`}</p>${searching?'<button class="button secondary" id="clear-search">Clear filters</button>':addButton(type)}</div>`;}
function renderOverview(){
 const d=data(),now=today();
 const due=d.vaccines.filter(r=>!r.administered).sort((a,b)=>a.scheduled.localeCompare(b.scheduled));
 const overdue=due.filter(r=>r.scheduled<now), low=d.inventory.filter(r=>stockStatus(r)!=='Available');
 const follow=d.growth.filter(r=>r.assessment==='Follow-up needed');
 const recent=[...d.visits].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);
 return heading(titles.overview,'For the people you know, and the community you care for.',addButton('mothers','Add a profile'))+
 `<div class="workspace-welcome"><div><h2>Every record is<br><em>someone's story.</em></h2><p>${new Date().toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · Saved on this device</p></div><span class="welcome-flower" aria-hidden="true">✳</span></div><div class="metrics"><div class="metric"><b>${d.mothers.length}</b><span>Maternal profiles</span></div><div class="metric"><b>${d.children.length}</b><span>Child profiles</span></div><div class="metric"><b>${overdue.length}</b><span>Overdue vaccinations</span></div><div class="metric"><b>${low.length}</b><span>Stock alerts</span></div></div><div class="workspace-columns"><section class="panel"><h2>The next care moments</h2>${due.slice(0,4).map(r=>`<a href="#workspace/vaccines" class="action-row"><div>${escape(patientLabel(r.patient))}<small>${escape(r.vaccine)} · ${escape(r.dose)} · ${fmt(r.scheduled)}</small></div>${badge(vaccineStatus(r))}</a>`).join('')||'<p>No pending vaccinations yet. Add staff-confirmed dates in Vaccinations.</p>'}<div class="button-stack"><a class="button secondary" href="#workspace/vaccines">View vaccinations ↗</a></div></section><section class="panel"><h2>A clear view of today</h2><a class="action-row" href="#workspace/visits"><div>Care notes<small>Checkups, symptoms & food records</small></div><span>${d.visits.length}</span></a><a class="action-row" href="#workspace/growth"><div>Growth follow-up<small>Staff-marked records for review</small></div><span>${follow.length}</span></a><a class="action-row" href="#workspace/inventory"><div>Vaccine stock alerts<small>Low stock or expired batches</small></div><span>${low.length}</span></a><a class="action-row" href="#workspace/backup"><div>Keep a copy close<small>Download a complete device backup</small></div><span>↗</span></a></section></div><section class="panel" style="margin-top:26px"><h2>Recent visits</h2>${recent.map(r=>`<div class="action-row"><div>${escape(patientLabel(r.patient))}<small>${fmt(r.date)} · ${escape(r.notes.slice(0,100))}</small></div>${editButton('visits',r.id)}</div>`).join('')||'<p>Your latest checkups and care notes will appear here.</p>'}<div class="button-stack">${addButton('visits','Record a visit')}</div></section><p class="data-note">This browser edition stores data separately from the Java apps. It does not send patient records to a cloud database. Use Data & backup to transfer profiles or make a complete backup.</p>`;
}
function rowCells(type,r){
 if(type==='mothers')return [`<strong>${escape(r.name)}</strong><small>${escape(r.id)}${r.barangay?' · '+escape(r.barangay):''}</small>`,`${r.age} years`,fmt(r.edd),badge(r.status),editButton(type,r.id)];
 if(type==='children')return [`<strong>${escape(r.name)}</strong><small>${escape(r.id)} · ${escape(r.gender)}</small>`,`${fmt(r.dob)}<small>${ageMonths(r.dob)} months</small>`,escape(r.motherName),badge(r.status),editButton(type,r.id)];
 if(type==='visits')return [`<strong>${escape(patientLabel(r.patient))}</strong><small>${fmt(r.date)}</small>`,`${escape(r.notes.slice(0,110))}${r.notes.length>110?'…':''}`,r.followUp?fmt(r.followUp):'—',editButton(type,r.id)];
 if(type==='vaccines')return [`<strong>${escape(patientLabel(r.patient))}</strong><small>${escape(r.vaccine)} · ${escape(r.dose)}</small>`,fmt(r.scheduled),r.administered?fmt(r.administered):'—',badge(vaccineStatus(r)),editButton(type,r.id)];
 if(type==='growth')return [`<strong>${escape(patientLabel(r.patient))}</strong><small>${fmt(r.date)}</small>`,`${r.weight} kg`,`${r.height} cm`,badge(r.assessment),editButton(type,r.id)];
 return [`<strong>${escape(r.vaccine)}</strong><small>Batch ${escape(r.batch)}</small>`,`${r.stock} doses<small>Alert at ${r.threshold} or fewer</small>`,fmt(r.expires),badge(stockStatus(r)),editButton(type,r.id)];
}
const headers={mothers:['Mother','Age','Expected delivery','Status','Actions'],children:['Child','Date of birth','Mother','Status','Actions'],visits:['Patient','Visit notes','Follow-up','Actions'],vaccines:['Patient & vaccine','Scheduled','Administered','Status','Actions'],growth:['Child','Weight','Length / height','Assessment','Actions'],inventory:['Vaccine & batch','Stock','Expiration','Status','Actions']};
function recordStatus(type,r){return type==='vaccines'?vaccineStatus(r):type==='inventory'?stockStatus(r):type==='growth'?r.assessment:r.status??'';}
function filtered(type){return data()[type].filter(r=>(filter==='All'||recordStatus(type,r)===filter)&&Object.values({...r,patient:patientLabel(r.patient??'')}).join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase()));}
function renderRecords(type){
 const opts=type==='mothers'||type==='children'?['Active','Inactive']:type==='vaccines'?['Overdue','Due today','Upcoming','Completed']:type==='inventory'?['Available','Low stock','Expired']:type==='growth'?['Not assessed','Reviewed','Follow-up needed']:[];
 const selected=filtered(type);
 let html=heading(titles[type],descriptions[type],addButton(type));
 if(type==='vaccines')html+='<p class="notice good">Enter vaccination dates confirmed by the health worker. E-Nay calculates due and overdue labels from those dates; it does not generate a clinical immunization schedule or send messages.</p>';
 if(type==='growth')html+='<p class="notice good">Measurements and follow-up flags are recorded by staff. The chart shows recorded weight over time; it does not calculate malnutrition diagnoses or WHO z-scores.</p>';
 html+=`<div class="toolbar"><label class="search-box"><span>Search ${titles[type].toLowerCase()}</span><input id="record-search" type="search" placeholder="Search name, ID, or details…" value="${escape(query)}"></label>${opts.length?`<label><span>Filter by status</span><select id="record-filter"><option>All</option>${opts.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select></label>`:''}</div><div id="record-results"><p class="record-count">${selected.length} of ${data()[type].length} records</p>${selected.length?table(headers[type],selected.map(r=>rowCells(type,r))):empty(type,!!query||filter!=='All')}</div>`;
 if(type==='growth'&&data().growth.length)html+=`<section class="growth-chart"><h2 class="section-title">A child's growth story</h2><label for="chart-patient">Choose a child</label><select id="chart-patient">${data().children.filter(c=>data().growth.some(g=>g.patient===c.id)).map(c=>`<option value="${escape(c.id)}">${escape(c.name)} · ${c.id}</option>`).join('')}</select><div id="chart-content"></div></section>`;
 return html;
}
function refreshResults(){const items=filtered(page);$('#record-results').innerHTML=`<p class="record-count">${items.length} of ${data()[page].length} records</p>${items.length?table(headers[page],items.map(r=>rowCells(page,r))):empty(page,!!query||filter!=='All')}`;}
function renderChart(id){const items=data().growth.filter(r=>r.patient===id).sort((a,b)=>a.date.localeCompare(b.date));if(!items.length)return;
 const start=new Date(items[0].date).getTime(),end=new Date(items.at(-1).date).getTime();
 const max=Math.max(...items.map(r=>r.weight))+1,min=Math.max(0,Math.min(...items.map(r=>r.weight))-1);
 const pts=items.map(r=>({x:60+(end===start?230:(new Date(r.date).getTime()-start)/(end-start)*450),y:155-(r.weight-min)/(max-min)*125,r}));
 $('#chart-content').innerHTML=`<svg viewBox="0 0 550 190" role="img" aria-label="Recorded weight in kilograms over measurement dates. Exact values are in the table below."><path d="M55 20V160H525" stroke="#bfc8b8" fill="none"/><text x="5" y="30" fill="#687168" font-size="11">${max.toFixed(1)} kg</text><text x="5" y="160" fill="#687168" font-size="11">${min.toFixed(1)} kg</text><polyline points="${pts.map(p=>`${p.x},${p.y}`).join(' ')}" stroke="#c77759" fill="none" stroke-width="2.5"/>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#234c3f"><title>${escape(fmt(p.r.date))}: ${p.r.weight} kg</title></circle>`).join('')}<text x="55" y="185" fill="#687168" font-size="10">${escape(fmt(items[0].date))}</text>${items.length>1?`<text x="525" y="185" fill="#687168" text-anchor="end" font-size="10">${escape(fmt(items.at(-1).date))}</text>`:''}</svg><p>Recorded weight only. A connected line is not a prediction or a reference growth standard.</p>${table(['Date','Weight','Length / height'],items.map(r=>[fmt(r.date),`${r.weight} kg`,`${r.height} cm`]))}`;
}
function renderBackup(){return heading('Keep a copy close.','Your records belong to this device. A backup helps you keep them.')+`<p class="notice good">No automatic synchronization: a phone and computer each have their own workspace. A complete backup includes all profiles, visits, vaccinations, growth records, and inventory. Keep backup files private.</p><div class="backup-grid"><section class="panel"><p class="eyebrow">01 / TAKE A COPY</p><h2>Complete workspace backup</h2><p>Download a JSON backup before changing phones or clearing browser data. Restoring it on another device transfers the full workspace.</p><div class="button-stack"><button class="button primary" id="download-backup" ${store.blocked?'disabled':''}>Download backup ↧</button><button class="button secondary" id="persist-storage">Keep device storage</button></div>${store.blocked?'<div class="button-stack"><button class="button secondary" id="download-original">Download original storage</button></div>':''}<p class="data-note">Browser storage is local to this site and browser profile. It is not an encrypted patient database. For this school build, use fictional records on a shared or unsecured device.</p></section><section class="panel"><p class="eyebrow">02 / BRING RECORDS IN</p><h2>Restore or import</h2><p>Choose a complete web backup, or a Java profile text file. You'll review the result before any records are replaced.</p><label for="import-kind">File type</label><select id="import-kind"><option value="backup">Complete web backup (.json)</option><option value="mothers">Java maternal profiles (.txt)</option><option value="children">Java child profiles (.txt)</option></select><label for="import-file">Choose a file to review</label><input id="import-file" type="file" accept=".json,application/json"><div id="import-preview" class="import-preview" aria-live="polite"></div></section><section class="panel"><p class="eyebrow">03 / JAVA COMPATIBILITY</p><h2>Profile text files</h2><p>Exports use the same normalized pipe-separated format as the Java app. Only its original profile fields are included. Contact details, barangay, and care records require the complete web backup.</p><div class="button-stack"><button class="button secondary" data-export="mothers" ${store.blocked?'disabled':''}>Maternal .txt ↧</button><button class="button secondary" data-export="children" ${store.blocked?'disabled':''}>Child .txt ↧</button></div><p class="data-note">Back up the Java data/ folder before replacing a file. Close the Java app before changing its data files.</p></section><section class="panel"><p class="eyebrow">04 / CARE ON THE GO</p><h2>Make room for offline care</h2><p>Install E-Nay on your phone, wait for “Offline ready,” and keep using the same browser profile. Installed mode and persistent storage depend on your browser.</p><div class="button-stack"><button class="button secondary install-action">Install on this device ↗</button><button class="button secondary" id="reload-storage">Reload local records</button></div></section></div>`;}
const guides=[
 {k:'MATERNAL CARE',title:'Make space for the conversation.',body:'Antenatal care includes nutrition counselling and ongoing contact with a health professional. Use each visit to record the mother’s questions, symptoms, and the follow-up agreed with her provider.',items:['Keep the expected delivery date and contact information current.','Record concerns in the visit notes for the attending health professional.','Use the local clinic’s approved care and referral protocols.'],source:'WHO · Nutrition counselling during pregnancy',url:'https://www.who.int/tools/elena/interventions/nutrition-counselling-pregnancy'},
 {k:'INFANT FEEDING',title:'Support the first two years.',body:'WHO recommends exclusive breastfeeding for the first six months, then safe, nutritionally adequate complementary foods with continued breastfeeding up to two years or beyond.',items:['Record feeding questions and dietary notes during the visit.','Ask the qualified health professional for individual feeding support.','Keep the child’s date of birth accurate so age is calculated correctly.'],source:'WHO · Infant and young child feeding',url:'https://www.who.int/news-room/fact-sheets/detail/infant-and-young-child-feeding'},
 {k:'GROWTH RECORDS',title:'Measure. Record. Review.',body:'Growth assessment uses weight and length or height, interpreted against appropriate growth standards. This version records measurements and staff-entered follow-up flags; it does not perform that clinical interpretation.',items:['Enter weight in kilograms and length or height in centimetres.','Check the measurement date and patient before saving.','Record the health worker’s assessment and next steps in the notes.'],source:'WHO · Growth assessment and counselling',url:'https://www.who.int/publications/m/item/10-steps-to-successful-growth-assessment-and-counselling'},
 {k:'BEFORE A HOME VISIT',title:'Bring the workspace with you.',body:'A little preparation makes offline visits easier. The workspace, these short guides, and your local records remain available after the first successful offline download.',items:['Wait for “Offline ready” while you still have a connection.','Open the profiles you need and check that your device is charged.','Download a complete backup regularly. External reading links need internet.'],source:'E-Nay · Local workspace guide',url:''}
];
function renderGuides(){return heading('A little guidance, close by.','These short guides are saved with the app. External reading needs a connection.')+`<p class="notice good">General information for health workers. Follow approved local protocols and qualified clinical guidance. Sources reviewed 18 October 2026.</p><div class="guide-grid">${guides.map((g,i)=>`<article><p class="eyebrow">0${i+1} / ${g.k}</p><h2>${g.title}</h2><p>${g.body}</p><ul>${g.items.map(x=>`<li>${x}</li>`).join('')}</ul>${g.url?`<a class="external-resource" href="${g.url}" target="_blank" rel="noopener noreferrer">${g.source} ↗</a>`:`<p class="data-note">${g.source}</p>`}</article>`).join('')}</div>`;}
function render(){
 updateStorageNotice();$('#page-content').innerHTML=page==='overview'?renderOverview():page==='backup'?renderBackup():page==='guides'?renderGuides():renderRecords(page);
 $('#workspace-nav').querySelectorAll('a').forEach(a=>{if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if($('#chart-patient'))renderChart($('#chart-patient').value);
}
function route(){const hash=location.hash.slice(1);const workspace=hash==='workspace'||hash.startsWith('workspace/');$('#home-view').hidden=workspace;$('#workspace-view').hidden=!workspace;
 $('.skip-link').href=workspace?'#workspace-main':'#main';
 if(workspace){const next=hash.split('/')[1]||'overview';page=Object.hasOwn(titles,next)?next:'overview';$('#mobile-page').value=page;query='';filter='All';importStage=null;render();}
 document.title=workspace?`${titles[page]} — E-Nay`:'E-Nay — Care, closer to home';
}
window.addEventListener('hashchange',()=>{route();if(location.hash.startsWith('#workspace')||location.hash==='#home'||!location.hash)window.scrollTo(0,0);});route();
const field=(key,label,kind='text',extra={})=>({key,label,kind,...extra});
function fields(type){
 const profile=[field('id','Profile ID','text',{hint:type==='mothers'?'M + exactly 3 digits, e.g. M001':'C + exactly 3 digits, e.g. C001',placeholder:type==='mothers'?'M001':'C001'}),field('name',type==='mothers'?'Mother’s name':'Child’s name','text',{autocomplete:'name'}),field('status','Monitoring status','select',{options:['Active','Inactive']}),field('contact','Contact number','tel',{optional:true,placeholder:'09… or +63…'}),field('barangay','Barangay / location','text',{optional:true,wide:true})];
 if(type==='mothers')return [profile[0],profile[1],field('age','Age in years','number',{min:12,max:60,step:1}),field('edd','Expected delivery date','date'),...profile.slice(2)];
 if(type==='children')return [profile[0],profile[1],field('gender','Sex recorded at birth','select',{options:['Female','Male']}),field('dob','Date of birth','date'),field('motherName','Mother’s name'),...profile.slice(2)];
 const patients=(type==='growth'?data().children:[...data().mothers,...data().children]).map(p=>({value:p.id,label:`${p.name} · ${p.id}`}));
 const patient=field('patient',type==='growth'?'Child profile':'Patient profile','select',{options:patients,wide:true});
 if(type==='visits')return [patient,field('date','Visit date','date'),field('followUp','Next follow-up','date',{optional:true}),field('bloodPressure','Blood pressure as recorded','text',{optional:true,placeholder:'e.g. 120/80 mmHg',hint:'Transcribe the clinician’s reading.'}),field('notes','Checkup notes','textarea',{wide:true}),field('symptoms','Reported symptoms','textarea',{wide:true,optional:true}),field('food','Food intake / dietary notes','textarea',{wide:true,optional:true})];
 if(type==='vaccines')return [patient,field('vaccine','Vaccine name'),field('dose','Dose / schedule label','text',{placeholder:'e.g. Dose 1'}),field('scheduled','Scheduled date','date'),field('administered','Date administered','date',{optional:true,hint:'Leave blank while the dose is pending.'}),field('notes','Notes','textarea',{optional:true,wide:true})];
 if(type==='growth')return [patient,field('date','Measurement date','date'),field('assessment','Health worker assessment','select',{options:['Not assessed','Reviewed','Follow-up needed']}),field('weight','Weight (kg)','number',{step:'any',min:.1,max:100}),field('height','Length / height (cm)','number',{step:'any',min:10,max:200}),field('notes','Assessment / follow-up notes','textarea',{optional:true,wide:true})];
 return [field('vaccine','Vaccine name'),field('batch','Batch ID'),field('stock','Available doses','number',{min:0,max:100000,step:1}),field('threshold','Low-stock alert at','number',{min:0,max:100000,step:1,hint:'Alert when available doses are at or below this number.'}),field('expires','Expiration date','date')];
}
function openForm(type,id=null){
 if(store.blocked){toast('Storage needs attention. Open Data & backup before making changes.');return;}
 if(!TYPES.includes(type))return;
 if(!['mothers','children','inventory'].includes(type)&&!(type==='growth'?data().children.length:data().mothers.length+data().children.length)){toast(type==='growth'?'Add a child profile before recording growth.':'Add a patient profile before recording care.');return;}
 lastFocus=document.activeElement;const original=id?data()[type].find(r=>r.id===id):null;if(id&&!original){toast('That record no longer exists. Reload the workspace.');return;}
 editing={type,id};$('#form-title').textContent=`${id?'Edit':'Add'} ${singles[type]}`;$('#form-error').hidden=true;
 const defaults={status:'Active',gender:'Female',assessment:'Not assessed',date:today(),threshold:5,stock:0};
 if(!id&&(type==='mothers'||type==='children')){const prefix=type==='mothers'?'M':'C';for(let n=1;n<=999;n++){const candidate=prefix+String(n).padStart(3,'0');if(!data()[type].some(r=>r.id===candidate)){defaults.id=candidate;break;}}}
 $('#form-fields').innerHTML=fields(type).map(f=>{const value=original?.[f.key]??defaults[f.key]??'';const opts=(f.options??[]).map(x=>typeof x==='string'?{value:x,label:x}:x);let control;
 const attrs=`id="field-${f.key}" name="${f.key}" ${!f.optional?'required':''} aria-describedby="error-${f.key}${f.hint?' hint-'+f.key:''}"`;
 if(f.kind==='select')control=`<select ${attrs}>${f.key==='patient'?'<option value="">Choose a profile…</option>':''}${opts.map(o=>`<option value="${escape(o.value)}" ${o.value===value?'selected':''}>${escape(o.label)}</option>`).join('')}</select>`;
 else if(f.kind==='textarea')control=`<textarea ${attrs} maxlength="2000">${escape(value)}</textarea>`;
 else control=`<input ${attrs} type="${f.kind}" value="${escape(value)}" ${f.placeholder?`placeholder="${escape(f.placeholder)}"`:''} ${f.autocomplete?`autocomplete="${f.autocomplete}"`:''} ${f.kind==='text'?'maxlength="100"':''} ${f.kind==='tel'?'maxlength="40"':''} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.step!==undefined?`step="${f.step}"`:''} ${f.key==='id'&&id?'disabled':''} ${f.kind==='number'?'inputmode="decimal"':''}>`;
 return `<div class="field ${f.wide?'wide':''} ${f.key==='name'||f.key==='motherName'?'wide-mobile':''}"><label for="field-${f.key}">${f.label}${f.optional?' <span>(optional)</span>':''}</label>${control}${f.hint?`<span class="hint" id="hint-${f.key}">${f.hint}</span>`:''}<span id="error-${f.key}" class="field-error" aria-live="polite"></span></div>`;}).join('');
 if(!id){if(type==='mothers')$('#field-edd').min=today();if(type==='children'){$('#field-dob').min=yearsBefore(today(),2);$('#field-dob').max=today();}}
 if($('#field-administered'))$('#field-administered').max=today();
 if($('#field-date'))$('#field-date').max=today();
 formBaseline=JSON.stringify(Object.fromEntries(new FormData($('#record-form'))));$('#form-dialog').showModal();
}
function closeForm(){const changed=JSON.stringify(Object.fromEntries(new FormData($('#record-form'))))!==formBaseline;if(changed&&!window.confirm('Discard the unsaved values in this form?'))return;$('#form-dialog').close();lastFocus?.focus();}
$('#close-form').onclick=closeForm;$('#cancel-form').onclick=closeForm;$('#form-dialog').addEventListener('cancel',e=>{e.preventDefault();closeForm();});
$('#record-form').onsubmit=async e=>{e.preventDefault();if(!editing)return;const form=e.currentTarget;const raw=Object.fromEntries(new FormData(form));if(editing.id)raw.id=editing.id;
 form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error').forEach(x=>x.textContent='');$('#form-error').hidden=true;
 const submit=form.querySelector('[type=submit]');submit.disabled=true;
 try{const save=()=>store.save(editing.type,raw,editing.id);if(navigator.locks)await navigator.locks.request('enay-record-write',save);else save();$('#form-dialog').close();render();toast('Record saved on this device.');lastFocus?.focus();}
 catch(error){$('#form-error').textContent=error.message;$('#form-error').hidden=false;if(error.field){const el=$(`#field-${error.field}`);if(el){el.setAttribute('aria-invalid','true');$(`#error-${error.field}`).textContent=error.message;el.focus();}}}
 finally{submit.disabled=false;}
};
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function stageImport(content,kind){
 let next,errors=[];const countBefore=TYPES.reduce((n,k)=>n+data()[k].length,0);
 if(kind==='backup')next=readEnvelope(content).data;
 else{
  if(store.blocked)throw new Error('Use a complete web backup to recover unreadable storage.');
  const parsed=parseText(content,kind);errors=parsed.errors;next=structuredClone(data());next[kind]=parsed.records;
  // Keep existing browser-only fields on a matching imported profile.
  next[kind]=next[kind].map(r=>({...r,contact:data()[kind].find(x=>x.id===r.id)?.contact??'',barangay:data()[kind].find(x=>x.id===r.id)?.barangay??''}));
  const ids=new Set([...next.mothers,...next.children].map(r=>r.id));
  if(['visits','vaccines','growth'].some(t=>next[t].some(r=>!ids.has(r.patient))))throw new Error('This import would remove profiles referenced by care records. Restore a complete backup or retain those profiles in the text file. Nothing was changed.');
 }
 importStage={next,raw:store.raw,errors};
 const count=TYPES.reduce((n,k)=>n+next[k].length,0);
 return `<div class="notice ${errors.length?'warning':'good'}"><strong>Ready to review</strong><br>${kind==='backup'?`Complete workspace: ${countBefore} existing records → ${count} imported records.`:`${next[kind].length} valid ${kind==='mothers'?'maternal':'child'} profiles. ${errors.length} invalid rows will be skipped.`}<br>Nothing has been changed yet.</div>${errors.length?`<ul>${errors.map(s=>`<li>${escape(s)}</li>`).join('')}</ul>`:''}<label class="confirm-check"><input id="confirm-import" type="checkbox"><span>I have reviewed this file and understand it will replace ${kind==='backup'?'all records in this workspace':`the ${kind==='mothers'?'maternal':'child'} profile list`}${errors.length?' and skip the invalid rows':''}.</span></label><button class="button primary" id="apply-import" disabled>Confirm & replace records</button>`;
}
document.addEventListener('click',async e=>{
 const add=e.target.closest('[data-add]'),edit=e.target.closest('[data-edit]'),exp=e.target.closest('[data-export]');
 if(add)openForm(add.dataset.add);
 if(edit)openForm(edit.dataset.edit,edit.dataset.id);
 if(exp)download(exp.dataset.export==='mothers'?'maternal_records.txt':'child_records.txt',toText(data()[exp.dataset.export],exp.dataset.export),'text/plain;charset=utf-8');
 if(e.target.closest('#clear-search')){query='';filter='All';render();}
 if(e.target.closest('#download-backup'))download(`E-Nay-backup-${today()}.json`,JSON.stringify(envelope(data()),null,2));
 if(e.target.closest('#download-original')){if(store.raw!==null)download(`E-Nay-original-storage-${today()}.txt`,store.raw,'text/plain');else toast('No stored data could be read. Check your browser’s storage permissions.');}
 if(e.target.closest('#reload-storage')){if(window.confirm('Reload records saved by other tabs? Any import preview will be cleared.')){store.load?.();importStage=null;render();toast(store.blocked?'Storage still needs attention.':'Local records reloaded.');}}
 if(e.target.closest('#persist-storage')){try{const allowed=await navigator.storage?.persist?.();toast(allowed?'Persistent storage granted. Continue to keep backups.':'Your browser did not grant persistent storage. Keep regular downloaded backups.');}catch{toast('Persistent storage is unavailable in this browser. Keep regular backups.');}}
 if(e.target.closest('#apply-import')&&importStage&&$('#confirm-import')?.checked){
  try{if(importStage.raw!==store.raw)throw new Error('Records changed after this preview. Choose the file again.');const restore=()=>store.commit(importStage.next,{recover:true});if(navigator.locks)await navigator.locks.request('enay-record-write',restore);else restore();importStage=null;render();toast('Reviewed records restored on this device.');}
  catch(error){$('#import-preview').insertAdjacentHTML('beforeend',`<p class="notice warning" role="alert">${escape(error.message)}</p>`);}
 }
 if(e.target.closest('.install-action'))installApp();
 if(e.target.closest('.external-resource')&&!navigator.onLine){e.preventDefault();toast('No internet connection. The external link is unavailable; the guide above still works offline.');}
 if(e.target.closest('#photo-credits'))info('Real people. Real photography.',`<p>The website uses licensed photography by human photographers. No AI-generated images are used.</p><p><a href="https://unsplash.com/photos/woman-carrying-baby-during-daytime-I0p_LTtA9yI" target="_blank" rel="noopener">Mother and baby — Bethany Beck / Unsplash</a><br><a href="https://unsplash.com/license" target="_blank" rel="noopener">Unsplash license</a></p><p><a href="https://www.pexels.com/photo/mother-and-baby-smiling-outdoors-27176239/" target="_blank" rel="noopener">Mother and baby outdoors — Helena Lopes / Pexels</a><br><a href="https://www.pexels.com/license/" target="_blank" rel="noopener">Pexels license</a></p><p>Photographs are illustrative. The people shown are not identified as E-Nay patients or endorsers.</p>`);
});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){query=e.target.value;refreshResults();}});
document.addEventListener('change',async e=>{
 if(e.target.id==='mobile-page')location.hash=e.target.value==='overview'?'workspace':`workspace/${e.target.value}`;
 if(e.target.id==='record-filter'){filter=e.target.value;refreshResults();}
 if(e.target.id==='chart-patient')renderChart(e.target.value);
 if(e.target.id==='confirm-import')$('#apply-import').disabled=!e.target.checked;
 if(e.target.id==='import-kind'){importStage=null;$('#import-file').value='';$('#import-file').accept=e.target.value==='backup'?'.json,application/json':'.txt,text/plain';$('#import-preview').innerHTML='';}
 if(e.target.id==='import-file'){
  importStage=null;const file=e.target.files?.[0],kind=$('#import-kind').value;if(!file)return;
  const preview=$('#import-preview');preview.textContent='Reading file…';
  try{if(file.size>10*1024*1024)throw new Error('Choose a file smaller than 10 MB. Nothing has been changed.');const content=await file.text();if(!document.contains(preview)||$('#import-kind').value!==kind||$('#import-file').files?.[0]!==file)return;preview.innerHTML=stageImport(content,kind);}
  catch(error){preview.innerHTML=`<p class="notice warning" role="alert">${escape(error.message)} Existing records were preserved.</p>`;}
 }
});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){toast('Records changed in another tab. Reload local records from Data & backup before saving.');if(!$('#form-dialog').open){store.load?.();if(!$('#workspace-view').hidden)render();}}});
window.addEventListener('beforeunload',e=>{if($('#form-dialog').open&&JSON.stringify(Object.fromEntries(new FormData($('#record-form'))))!==formBaseline){e.preventDefault();e.returnValue='';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('appinstalled',()=>{installEvent=null;toast('E-Nay is installed. Wait for Offline ready before disconnecting.');});
async function installApp(){if(installEvent){await installEvent.prompt();installEvent=null;return;}info('Take E-Nay with you.',`<p><strong>Android:</strong> Open this site in Chrome or Edge, open the browser menu, then choose “Install app” or “Add to Home screen.”</p><p><strong>iPhone or iPad:</strong> Open this site in Safari, tap Share, then “Add to Home Screen.”</p><p><strong>Computer:</strong> Use your browser’s install icon or app menu when available.</p><p>Open the installed app while connected and wait for <strong>Offline ready</strong>. Records stay in this device’s browser storage; keep a downloaded backup. Installation availability depends on your browser.</p>`);}
function connection(){const status=$('#offline-status');status.textContent=offlineReady?(navigator.onLine?'Offline ready · Saved on device':'Offline · Saved on device'):(navigator.onLine?'Preparing offline access…':'Offline copy not confirmed');}
window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
if('serviceWorker' in navigator){
 navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_READY'){offlineReady=true;connection();}});
 navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(reg=>{(navigator.serviceWorker.controller??reg.active)?.postMessage({type:'CHECK_OFFLINE'});}).catch(()=>{$('#offline-status').textContent='Offline setup unavailable';});
 navigator.serviceWorker.addEventListener('controllerchange',()=>navigator.serviceWorker.controller?.postMessage({type:'CHECK_OFFLINE'}));
}else $('#offline-status').textContent='Browser does not support offline access';
